import { defineConfig } from 'astro/config';

export default defineConfig({
  output: 'static',
});

---
interface Props {
  id: string;
}

const { id } = Astro.props;
const fieldId = `${id}-email`;
---

<form id={id} class="email" action="https://thisweeksouthbay.beehiiv.com" method="get">
  <label class="visually-hidden" for={fieldId}>Email</label>
  <input id={fieldId} type="email" name="email" autocomplete="email" placeholder="you@" />
  <a href="https://thisweeksouthbay.beehiiv.com">Monday email. 7am.</a>
</form>

<style>
  .visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
</style>

---
import type { ListingEvent } from '../lib/events';
import { formatTimeRange } from '../lib/events';

interface Props {
  event: ListingEvent;
}

const { event } = Astro.props;
const time = formatTimeRange(event);
---

<li class="row">
  <time class="time" datetime={event.start}>{time}</time>
  <a class="title" href={`/event/${event.slug}`}>{event.title}</a>
  <span class="meta">{event.venue}</span>
  <span class="city">{event.city}</span>
  <span class="cost">{event.cost}</span>
</li>

import data from '../data/events.json';

export type ListingEvent = {
  slug: string;
  title: string;
  start: string;
  end: string | null;
  city: string;
  venue: string;
  address: string;
  category: string;
  cost: string;
  audience: string;
  url: string;
  blurb: string;
};

export type Issue = {
  weekStart: string;
  weekEnd: string;
  label: string;
};

export type EventsFile = {
  issue: Issue;
  nextIssue: Issue;
  events: ListingEvent[];
};

export const catalog = data as EventsFile;
export const nextIssue = catalog.nextIssue;

const TZ = 'America/Los_Angeles';

const weekdayLong = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ,
  weekday: 'long',
});

const weekdayShort = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ,
  weekday: 'short',
});

const dateLong = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ,
  weekday: 'long',
  month: 'long',
  day: 'numeric',
  year: 'numeric',
});

const dateParts = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

const timeParts = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ,
  hour: 'numeric',
  minute: '2-digit',
  hour12: true,
});

export function laDateKey(iso: string): string {
  const parts = dateParts.formatToParts(new Date(iso));
  const year = parts.find((p) => p.type === 'year')?.value;
  const month = parts.find((p) => p.type === 'month')?.value;
  const day = parts.find((p) => p.type === 'day')?.value;
  return `${year}-${month}-${day}`;
}

function isMultiDay(event: ListingEvent): boolean {
  if (!event.end) return false;
  return laDateKey(event.start) !== laDateKey(event.end);
}

export function overlapsIssue(event: ListingEvent, issue: Issue): boolean {
  const startDay = laDateKey(event.start);
  const endDay = event.end ? laDateKey(event.end) : startDay;
  return startDay <= issue.weekEnd && endDay >= issue.weekStart;
}

/** Include an event iff its LA start date falls within the issue window. */
export function weekEvents(issue: Issue = catalog.issue): ListingEvent[] {
  return catalog.events
    .filter((event) => {
      const startDay = laDateKey(event.start);
      return startDay >= issue.weekStart && startDay <= issue.weekEnd;
    })
    .sort((a, b) => a.start.localeCompare(b.start));
}

export function getEvent(slug: string): ListingEvent | undefined {
  return catalog.events.find((event) => event.slug === slug);
}

export function weekdayLabel(iso: string): string {
  return weekdayLong.format(new Date(iso)).toUpperCase();
}

export function formatClock(iso: string): string {
  const parts = timeParts.formatToParts(new Date(iso));
  const hour = parts.find((p) => p.type === 'hour')?.value ?? '';
  const minute = parts.find((p) => p.type === 'minute')?.value ?? '';
  const dayPeriod = (parts.find((p) => p.type === 'dayPeriod')?.value ?? '')
    .replace(/\s/g, '')
    .toLowerCase();
  if (minute === '00') return `${hour}${dayPeriod}`;
  return `${hour}:${minute}${dayPeriod}`;
}

export function formatTimeRange(event: ListingEvent): string {
  if (isMultiDay(event) && event.end) {
    return `${weekdayShort.format(new Date(event.start))}–${weekdayShort.format(new Date(event.end))}`;
  }
  const start = formatClock(event.start);
  if (!event.end) return start;
  return `${start}–${formatClock(event.end)}`;
}

export function formatWhen(event: ListingEvent): string {
  const day = dateLong.format(new Date(event.start));
  if (isMultiDay(event) && event.end) {
    return `${day}–${dateLong.format(new Date(event.end))}`;
  }
  if (event.end) return `${day}, ${formatClock(event.start)}–${formatClock(event.end)}`;
  return `${day}, ${formatClock(event.start)}`;
}

export type DayGroup = {
  key: string;
  label: string;
  events: ListingEvent[];
};

export function groupByWeekday(events: ListingEvent[]): DayGroup[] {
  const groups: DayGroup[] = [];
  const index = new Map<string, DayGroup>();

  for (const event of events) {
    const key = laDateKey(event.start);
    let group = index.get(key);
    if (!group) {
      group = { key, label: weekdayLabel(event.start), events: [] };
      index.set(key, group);
      groups.push(group);
    }
    group.events.push(event);
  }

  return groups;
}

export function mapsUrl(address: string): string {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
}

export function allSlugs(): string[] {
  return catalog.events.map((event) => event.slug);
}

---
import Layout from '../../layouts/Layout.astro';
import { allSlugs, formatWhen, getEvent, mapsUrl } from '../../lib/events';

export function getStaticPaths() {
  return allSlugs().map((slug) => ({ params: { slug } }));
}

const { slug } = Astro.params;
const event = getEvent(slug);

if (!event) {
  throw new Error(`Unknown event: ${slug}`);
}

const when = formatWhen(event);
const maps = mapsUrl(event.address);
---

<Layout title={`${event.title} — This Week South Bay`} current="event" description={event.blurb}>
  <article class="detail">
    <h1>{event.title}</h1>
    <dl>
      <dt>When</dt>
      <dd>
        <time datetime={event.start}>{when}</time>
      </dd>
      <dt>Where</dt>
      <dd>
        {event.city}<br />
        {event.venue}<br />
        {event.address}
      </dd>
      {
        event.cost ? (
          <>
            <dt>Cost</dt>
            <dd>{event.cost}</dd>
          </>
        ) : null
      }
    </dl>
    <p class="blurb">{event.blurb}</p>
    {
      event.url ? (
        <a class="source" href={event.url}>
          {event.url}
        </a>
      ) : null
    }
    <a class="maps" href={maps}>Map</a>
  </article>
</Layout>

---
import Layout from '../layouts/Layout.astro';
import EventRow from '../components/EventRow.astro';
import { catalog, groupByWeekday, weekEvents } from '../lib/events';

const days = groupByWeekday(weekEvents());
---

<Layout title="This Week South Bay" current="week">
  <header class="masthead">
    <p class="kicker">This Week</p>
    <p class="cities">
      Hermosa · MB · Redondo<br />
      El Segundo · Torrance
    </p>
    <p class="issue">{catalog.issue.label}</p>
    <p class="line">Monday email. 7am. Nights out, not news. Updated daily.</p>
  </header>

  {
    days.map((day) => (
      <section class="day">
        <h2 class="day-label">{day.label}</h2>
        <ol class="list">
          {day.events.map((event) => (
            <EventRow event={event} />
          ))}
        </ol>
      </section>
    ))
  }
</Layout>

---
import Layout from '../layouts/Layout.astro';
import EventRow from '../components/EventRow.astro';
import { catalog, groupByWeekday, weekEvents } from '../lib/events';

const days = groupByWeekday(weekEvents(catalog.nextIssue));
---

<Layout title="Next Week — This Week South Bay" current="next">
  <header class="masthead">
    <p class="kicker">Next Week</p>
    <p class="cities">
      Hermosa · MB · Redondo<br />
      El Segundo · Torrance
    </p>
    <p class="issue">{catalog.nextIssue.label}</p>
    <p class="line">Monday email. 7am. Nights out, not news. Updated daily.</p>
  </header>

  {
    days.length === 0 ? (
      <article class="spare">
        <p>Board is filling.</p>
      </article>
    ) : (
      days.map((day) => (
        <section class="day">
          <h2 class="day-label">{day.label}</h2>
          <ol class="list">
            {day.events.map((event) => (
              <EventRow event={event} />
            ))}
          </ol>
        </section>
      ))
    )
  }
</Layout>

:root {
  --cream: #faf7f0;
  --ink: #121212;
  --muted: #464646;
  --bar: 3px;
  --page: 1.25rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  background: var(--cream);
  color: var(--ink);
  overflow-x: clip;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: 'Public Sans', ui-sans-serif, system-ui, sans-serif;
  font-weight: 400;
  font-size: 1rem;
  line-height: 1.4;
  background: var(--cream);
  color: var(--ink);
  border-left: var(--bar) solid var(--ink);
  overflow-x: clip;
}

a {
  color: inherit;
  text-underline-offset: 0.12em;
}

a:hover {
  text-decoration-thickness: 2px;
}

:focus-visible {
  outline: 1px solid var(--ink);
  outline-offset: 3px;
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding-left: var(--page);
  padding-left: calc(var(--page) + env(safe-area-inset-left, 0px));
  padding-right: var(--page);
  padding-right: calc(var(--page) + env(safe-area-inset-right, 0px));
}

.chrome {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding-top: 1.1rem;
  padding-bottom: 1.1rem;
}

.wordmark {
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  width: fit-content;
}

.wordmark:hover {
  text-decoration: none;
}

.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem 1.15rem;
}

.nav a {
  color: var(--ink);
  text-decoration: none;
}

.nav a[aria-current='page'] {
  text-decoration: underline;
}

.email {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.7rem;
}

.email input {
  appearance: none;
  width: 10.5rem;
  max-width: 100%;
  border: 0;
  border-bottom: 1px solid var(--ink);
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 0.95rem;
  padding: 0.15rem 0 0.2rem;
}

.email input::placeholder {
  color: var(--muted);
}

.email a {
  color: var(--muted);
  text-decoration: none;
  white-space: nowrap;
}

.email a:hover {
  text-decoration: underline;
}

.signup-jump {
  color: var(--muted);
  text-decoration: none;
  white-space: nowrap;
}

.signup-jump:hover {
  text-decoration: underline;
}

.main {
  flex: 1;
  padding-bottom: 4rem;
  max-width: 52rem;
}

.masthead {
  padding-top: 2.75rem;
  padding-bottom: 2.4rem;
}

.kicker {
  margin: 0 0 0.7rem;
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
}

.cities {
  margin: 0;
  font-size: clamp(1.55rem, 6.2vw, 2.35rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.02em;
}

.issue {
  margin: 1.35rem 0 0;
  color: var(--muted);
}

.line {
  margin: 0.35rem 0 0;
  color: var(--ink);
}

.day {
  margin: 0 0 2.4rem;
}

.day-label {
  margin: 0 0 0.55rem;
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.15rem 1.25rem;
  padding: 0.85rem 0;
  border-top: 1px solid var(--ink);
}

.row:last-child {
  border-bottom: 1px solid var(--ink);
}

.time {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.title {
  font-weight: 700;
  text-decoration: none;
}

.meta {
  color: var(--ink);
}

.city {
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.cost {
  color: var(--muted);
}

.detail {
  padding-top: 2.75rem;
  max-width: 28rem;
}

.detail h1 {
  margin: 0 0 1.6rem;
  font-size: clamp(1.7rem, 6vw, 2.4rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.02em;
}

.detail dl {
  margin: 0 0 1.6rem;
}

.detail dt {
  margin: 1.1rem 0 0.2rem;
  font-size: 0.68rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
}

.detail dd {
  margin: 0;
}

.blurb {
  margin: 0 0 1.8rem;
}

.maps,
.source {
  display: block;
  margin: 0 0 0.55rem;
  overflow-wrap: anywhere;
  color: var(--muted);
}

.maps {
  width: fit-content;
}

.spare {
  padding-top: 2.75rem;
  max-width: 26rem;
}

.spare h1 {
  margin: 0 0 1.4rem;
  font-size: clamp(1.7rem, 6vw, 2.4rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.02em;
}

.spare p {
  margin: 0 0 1rem;
  max-width: 22rem;
}

.spare p:last-child {
  margin-bottom: 0;
}

.foot {
  padding: 2rem 0 2.4rem;
  max-width: 52rem;
}

.foot-url {
  margin: 1.1rem 0 0;
  color: var(--muted);
}

.foot-url a {
  color: inherit;
  text-decoration: none;
}

.foot-url a:hover {
  text-decoration: underline;
}

@media (min-width: 720px) {
  :root {
    --page: 2.5rem;
  }

  .chrome {
    flex-direction: row;
    align-items: baseline;
    justify-content: space-between;
    gap: 1.5rem;
    padding-top: 1.35rem;
  }

  .chrome-start {
    display: flex;
    align-items: baseline;
    gap: 2rem;
  }

  .masthead {
    padding-top: 4.5rem;
    padding-bottom: 3.2rem;
  }

  .row {
    grid-template-columns: 6.75rem minmax(0, 1.4fr) minmax(0, 1.1fr) 7.5rem 6.25rem;
    align-items: baseline;
    padding: 0.72rem 0;
  }

  .row .time {
    grid-column: 1;
  }

  .row .title {
    grid-column: 2;
    min-width: 0;
  }

  .row .meta {
    grid-column: 3;
    min-width: 0;
  }

  .row .city {
    grid-column: 4;
  }

  .row .cost {
    grid-column: 5;
    text-align: right;
  }

  .detail,
  .spare {
    padding-top: 4.5rem;
  }
}

@media (min-width: 1040px) {
  :root {
    --page: 4rem;
  }

  .main {
    max-width: 58rem;
  }
}
